1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	#include <cstdio>
8	#include <cstdlib>
9	#include <exception>
10	#include <string>
11	#include <string_view>
12	
13	#include "cli.hpp"
14	#include "dev_mode.hpp"
15	#include "log.hpp"
16	
17	namespace andes_sim {
18	int cmd_list(const Cli& cli);
19	int cmd_doctor(const Cli& cli);
20	int cmd_run(const Cli& cli);
21	}  // namespace andes_sim
22	
23	namespace {
24	
25	using andes_sim::Cli;
26	using andes_sim::cmd_doctor;
27	using andes_sim::cmd_list;
28	using andes_sim::cmd_run;
29	using andes_sim::is_dev_mode;
30	
31	// The known command names live in cli.cpp (is_subcommand): the parser needs
32	// them for the default-command rule, so parse_cli only ever yields run/list/
33	// doctor (or "" for no args / top-level help). Developer build/test/state-diff
34	// tooling lives in scripts/, not the binary.
35	
36	// ---- help model: the user-facing surface rendered as a command tree --------
37	//
38	// `run`'s two subcommand groups -- the modes (the composition axis) ...
39	struct ModeRow {
40	  const char* name;
41	  const char* brief;
42	};
43	constexpr ModeRow kRunModes[] = {
44	    {"fast", "QEMU only -- functional, full speed"},
45	    {"cycle", "one cycle-accurate engine, from reset"},
46	    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
47	};
48	
49	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
50	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
51	struct TargetRow {
52	  const char* name;
53	  const char* brief;
54	  bool dev;
55	};
56	constexpr TargetRow kListTargets[] = {
57	    {"models", "the modes and their engines", false},
58	    {"engines", "discovered cycle-accurate engines", false},
59	    {"fixtures", "internal test ELFs (developer target)", true},
60	};
61	
62	// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
63	// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
64	// it is required); `dev` hides it unless ANDESIM_DEV is set.
65	struct OptRow {
66	  const char* flag;  // includes its own leading indent
67	  const char* tag;
68	  const char* brief;
69	  bool dev;
70	};
71	constexpr OptRow kRunOpts[] = {
72	    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
73	    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
74	    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
75	    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
76	    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
77	    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
78	    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
79	    {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)", false},
80	    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
81	    {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)", false},
82	    {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)", false},
83	    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
84	    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
85	    {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)", false},
86	    {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level", false},
87	    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle only; hybrid rejects -- args)", false},
88	};
89	
90	// A major command line at column 0: `name   brief`.
91	void print_major(std::FILE* out, const char* name, const char* brief) {
92	  std::fprintf(out, "%-7s %s\n", name, brief);
93	}
94	
95	// A subcommand/target line, indented two under its command: `  name   brief`.
96	void print_sub(std::FILE* out, const char* name, const char* brief) {
97	  std::fprintf(out, "  %-9s %s\n", name, brief);
98	}
99	
100	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
101	void print_opt(std::FILE* out, const OptRow& o) {
102	  if (o.tag[0])
103	    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
104	  else
105	    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
106	}
107	
108	// `run`: major line, the mode subcommands, then the option list (dev options
109	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
110	void print_run_block(std::FILE* out) {
111	  print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
112	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
113	  std::fputs("\n", out);
114	  for (const OptRow& o : kRunOpts) {
115	    if (o.dev && !is_dev_mode()) continue;
116	    print_opt(out, o);
117	  }
118	}
119	
120	void print_list_block(std::FILE* out) {
121	  print_major(out, "list", "list what is available");
122	  for (const TargetRow& t : kListTargets) {
123	    if (t.dev && !is_dev_mode()) continue;
124	    print_sub(out, t.name, t.brief);
125	  }
126	}
127	
128	void print_doctor_block(std::FILE* out) {
129	  print_major(out, "doctor", "check toolchain + fixtures are present");
130	}
131	
132	// Top-level `andesim --help`: the whole tree -- every major command, its
133	// subcommands, and run's full option list, so one screen shows everything.
134	void print_usage(std::FILE* out) {
135	  std::fputs("usage: andesim [command] [options] <ELF> [-- <engine args>]\n\n",
136	             out);
137	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
138	             out);
139	  print_run_block(out);
140	  std::fputs("\n", out);
141	  print_list_block(out);
142	  std::fputs("\n", out);
143	  print_doctor_block(out);
144	  std::fputs(
145	      "\n'andesim run --help' / 'andesim list --help' for per-command "
146	      "detail.\n",
147	      out);
148	}
149	
150	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
151	// parse_cli admits only run/list/doctor, so `run` is the fallthrough.
152	void print_subcommand_help(std::string_view name, std::FILE* out) {
153	  if (name == "list") { print_list_block(out); return; }
154	  if (name == "doctor") { print_doctor_block(out); return; }
155	  print_run_block(out);
156	}
157	
158	}  // namespace
159	
160	int main(int argc, char** argv) {
161	  using namespace andes_sim;
162	
163	  Cli cli = parse_cli(argc, argv);
164	  if (!cli.error.empty()) {
165	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
166	    return 2;
167	  }
168	
169	  if (!set_log_threshold(cli.log_level)) {
