1	/* LM content transport e2e (ROADMAP_ilm_dlm F4a): DLM data round-trip.
2	 *
3	 *   QEMU 1: enable the DLM (csr 0x7C1 mdlmb.EN=1 -- the premium RTL resets
4	 *           EN=0, and this CSR write is what arms the write-mask restore on
5	 *           the vsim leg), then fill the whole 32 KB window with a
6	 *           runtime-COMPUTED pattern through the hart-local view (0x200000).
7	 *   vsim:   inside the ROI, re-derive the formula and compare every word of
8	 *           the DLM, then print the verdict (DLM_OK / DLM_BAD). The harness
9	 *           greps the vsim log (CHECK_VSIM_STDOUT=DLM_OK); code after the
10	 *           exit marker never runs on the vsim leg, so the verdict must be
11	 *           printed INSIDE the ROI (this fixture measures correctness, not
12	 *           cycles -- the UART cost is irrelevant).
13	 *
14	 * Why this is decisive for the transport: the pattern bytes exist NOWHERE
15	 * except the local memory. They are runtime-computed (not in the ELF), and
16	 * the QEMU-phase stores land in the per-CPU DLM overlay -- NOT the shared
17	 * DRAM mmap (QEMU maps the TCM in cpu_as_root; the ELF loader and the mmap
18	 * only cover system DRAM). The ONLY road they can travel to the vsim RTL's
19	 * DLM SRAM is the sidecar transport: plugin slave-port drain ->
20	 * <state>.dlm -> --dlm backdoor load. No transport => vsim reads
21	 * reset-empty SRAM => DLM_BAD.
22	 *
23	 * Geometry: premium hart-0 DLM = 32 KB at hart-local 0x200000 (the program
24	 * image ends ~0x10a000 and the stack sits at 0x700000, so nothing else
25	 * touches the window). ILM code transport is F4b's job.
26	 */
27	#include "runtime/rt_c_helpers.h"
28	
29	#include <stdint.h>
30	#include <stdio.h>
31	
32	#define DLM_BASE  0x200000u
33	#define DLM_BYTES 32768u
34	#define DLM_WORDS (DLM_BYTES / 4u)
35	
36	/* Per-word pattern: cheap, position-dependent, never all-zero. */
37	static inline uint32_t pat(uint32_t i) { return i * 2654435761u + 0x5A17u; }
38	
39	int main(void)
40	{
41	  volatile uint32_t *dlm = (volatile uint32_t *) (uintptr_t) DLM_BASE;
42	
43	  enable_dlm();
44	
45	  /* QEMU phase: runtime-computed fill. Also init stdio here so the ROI's
46	   * verdict printf does not pay first-call setup inside the window. */
47	  for (uint32_t i = 0; i < DLM_WORDS; i++) dlm[i] = pat(i);
48	  printf("DLM filled\n");
49	  fflush(stdout);
50	
51	  enter_vsim();
52	
53	  /* vsim ROI: every word must have crossed the handoff intact. */
54	  uint32_t bad = 0, first = 0;
55	  for (uint32_t i = 0; i < DLM_WORDS; i++) {
56	    if (dlm[i] != pat(i)) {
57	      if (bad == 0) first = i;
58	      bad++;
59	    }
60	  }
61	  if (bad == 0) {
62	    printf("DLM_OK words=%u\n", (unsigned) DLM_WORDS);
63	  } else {
64	    printf("DLM_BAD count=%u first=%u got=0x%08x want=0x%08x\n",
65	           (unsigned) bad, (unsigned) first, (unsigned) dlm[first],
66	           (unsigned) pat(first));
67	  }
68	  fflush(stdout);
69	
70	  exit_vsim();
71	
72	  return bad != 0;
73	}
74

